//! Zonos2 family tests: fixture parity against the pinned reference
//! (`testdata/tts_zonos2/`, regenerated by
//! `tools/gen_zonos2_fixtures.py`) plus prompt-math and sampling unit
//! checks.

use std::path::{Path, PathBuf};

use super::{
    shear, shear_up, silence_prompt_tokens, text_to_byte_ids, GenerationState, Model, ModelConfig,
    TtsSamplingParams,
};
use crate::SpeechError;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_zonos2")
        .join(name)
}

fn read_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(testdata(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

fn ids(value: &serde_json::Value) -> Vec<i32> {
    value
        .as_array()
        .expect("id list")
        .iter()
        .map(|v| v.as_i64().expect("i32") as i32)
        .collect()
}

fn table(value: &serde_json::Value) -> Vec<Vec<i32>> {
    value.as_array().expect("table").iter().map(ids).collect()
}

fn open_case(case: &str) -> Model {
    Model::open(&testdata(case)).expect("open model")
}

#[test]
fn prompt_rows_match_the_reference_traces() {
    let traces = read_json("prompt/traces.json");
    let model = open_case("generate");
    for case in traces["cases"].as_array().expect("cases") {
        let speaking_rate = case["speaking_rate_bucket"].as_u64().map(|v| v as usize);
        let quality: Vec<Option<usize>> = case["quality_buckets"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_u64().map(|n| n as usize)).collect())
            .unwrap_or_default();
        let speaker = case["speaker_conditioned"].as_bool().unwrap();
        let (rows, speaker_pos) = model
            .build_prompt_rows(
                case["text"].as_str().unwrap(),
                speaking_rate,
                &quality,
                speaker,
                case["clean_speaker_background"].as_bool().unwrap(),
                case["accurate_mode"].as_bool().unwrap(),
            )
            .unwrap();
        assert_eq!(rows, table(&case["rows"]), "case {}", case["name"]);
        let want_pos = case["speaker_position"].as_u64().map(|v| v as usize);
        assert_eq!(speaker_pos, want_pos);
    }
}

#[test]
fn hidden_states_and_logits_match_the_reference() {
    let traces = read_json("forward/traces.json");
    let model = open_case("generate");
    for case in traces["cases"].as_array().expect("cases") {
        let frames: Vec<i32> = table(&case["frames"]).into_iter().flatten().collect();
        let speaker: Option<Vec<f32>> = case["speaker_embedding"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_f64().unwrap() as f32).collect());
        let hidden = model
            .forward_hidden(
                &frames,
                None,
                speaker.as_deref(),
                case["speaker_position"].as_u64().map(|v| v as usize),
            )
            .unwrap();
        let want_hidden: Vec<f32> = case["hidden"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap() as f32)
            .collect();
        let tolerance = case["tolerance"].as_f64().unwrap() as f32;
        let mut max_diff = 0.0f32;
        for (a, b) in hidden.iter().zip(&want_hidden) {
            max_diff = max_diff.max((a - b).abs());
        }
        assert!(
            max_diff <= tolerance,
            "case {} hidden diff {max_diff} > {tolerance}",
            case["name"]
        );
        let logits = model.compute_logits(&hidden, frames.len() / model.config.frame_width());
        let want_logits: Vec<f32> = case["logits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap() as f32)
            .collect();
        let mut logit_diff = 0.0f32;
        for (a, b) in logits.iter().zip(&want_logits) {
            logit_diff = logit_diff.max((a - b).abs());
        }
        assert!(
            logit_diff <= tolerance,
            "case {} logits diff {logit_diff} > {tolerance}",
            case["name"]
        );
    }
}

#[test]
fn greedy_generation_matches_the_reference() {
    let traces = read_json("generate/traces.json");
    let model = open_case("generate");
    for scenario in traces["scenarios"].as_array().expect("scenarios") {
        let params: TtsSamplingParams =
            serde_json::from_value(scenario["params"].clone()).expect("params");
        let speaker: Option<Vec<f32>> = scenario["speaker_embedding"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_f64().unwrap() as f32).collect());
        let quality: Vec<Option<usize>> = scenario["quality_buckets"]
            .as_array()
            .map(|a| a.iter().map(|v| v.as_u64().map(|n| n as usize)).collect())
            .unwrap_or_default();
        let (generated, eos_frame) = model
            .generate(
                scenario["text"].as_str().unwrap(),
                &params,
                speaker.as_deref(),
                scenario["clean_speaker_background"]
                    .as_bool()
                    .unwrap_or(false),
                scenario["accurate_mode"].as_bool().unwrap_or(true),
                scenario["speaking_rate_bucket"]
                    .as_u64()
                    .map(|v| v as usize),
                &quality,
                scenario["seed"].as_u64().unwrap_or(0),
            )
            .unwrap();
        assert_eq!(
            generated,
            table(&scenario["generated"]),
            "scenario {}",
            scenario["name"]
        );
        let want_eos = scenario["eos_frame"].as_u64().map(|v| v as usize);
        assert_eq!(eos_frame, want_eos);
    }
}

#[test]
fn decode_audio_matches_the_reference_dac_trace() {
    let traces = read_json("generate/traces.json");
    let decode = &traces["decode"];
    let scenario = traces["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .find(|s| s["name"] == decode["scenario"])
        .expect("decode scenario")
        .clone();
    let model = open_case("generate");
    let dac = crate::codec::descript::Dac::open(&testdata("dac")).expect("open dac");
    let audio = model
        .decode_audio(
            &dac,
            &table(&scenario["generated"]),
            scenario["eos_frame"].as_u64().map(|v| v as usize),
        )
        .unwrap();
    let want: Vec<f32> = decode["audio"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap() as f32)
        .collect();
    let tolerance = decode["audio_tolerance"].as_f64().unwrap() as f32;
    assert_eq!(audio.len(), want.len(), "decoded sample count");
    let mut max_diff = 0.0f32;
    for (a, b) in audio.iter().zip(&want) {
        max_diff = max_diff.max((a - b).abs());
    }
    assert!(
        max_diff <= tolerance,
        "decode diff {max_diff} > {tolerance}"
    );
}

#[test]
fn sample_frame_math_matches_fixed_logit_traces() {
    let traces = read_json("sampling/traces.json");
    let config = ModelConfig::from_json(&read_json("generate/config.json")).unwrap();
    for case in traces["cases"].as_array().expect("cases") {
        let params: TtsSamplingParams =
            serde_json::from_value(case["params"].clone()).expect("params");
        let mut state =
            GenerationState::new(config.n_codebooks, config.eoa_id, config.text_vocab as i32);
        for frame in table(&case["generated_history"]) {
            state.append(&frame, false);
        }
        let logits: Vec<f32> = case["logits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap() as f32)
            .collect();
        let got = super::sample_frame(
            &logits,
            config.n_codebooks,
            config.audio_vocab_size(),
            &state,
            &params,
            &mut crate::music::minimax_music3::rng::KeySequence::new(0),
        );
        assert_eq!(got, ids(&case["frame"]), "case {}", case["name"]);
    }
}

#[test]
fn shear_round_trip_and_silence_match_the_reference() {
    let traces = read_json("prompt/traces.json");
    let sheared = shear(&table(&traces["shear"]["plain"]), 1025).unwrap();
    assert_eq!(sheared, table(&traces["shear"]["sheared"]));
    // The reference shear_up is a lossy partial inverse (lanes past
    // the table length read the pad); pin the exact recorded values.
    let up = shear_up(&table(&traces["shear"]["sheared"]), 1025).unwrap();
    assert_eq!(up, table(&traces["shear"]["unsheared"]));
    let silence = silence_prompt_tokens(3, 1025, 455);
    assert_eq!(silence, table(&traces["silence"]));
}

#[test]
fn text_byte_ids_encode_utf8() {
    assert_eq!(text_to_byte_ids(""), vec![2, 3]);
    assert_eq!(text_to_byte_ids("A"), vec![2, 192 + 65, 3]);
    assert_eq!(
        text_to_byte_ids("\u{1F600}").len(),
        6,
        "a four-byte emoji plus BOS and EOS"
    );
}

#[test]
fn generation_state_tracks_eos_countdown() {
    let mut state = GenerationState::new(3, 1024, 455);
    state.append(&[0, 1, 2, 455], false);
    assert!(state.eos_frame.is_none());
    // The eos lands on codebook 1 of step 1: eos_frame = 1 - 1 = 0,
    // countdown 4 counts the eos frame itself.
    state.append(&[0, 1024, 2, 455], false);
    assert_eq!(state.eos_frame, Some(0));
    assert_eq!(state.eos_countdown, 3);
    state.append(&[0, 1, 2, 455], false);
    state.append(&[0, 1, 2, 455], false);
    state.append(&[0, 1, 2, 455], false);
    assert!(state.finished());
    assert_eq!(state.generated.len(), 5);
}

#[test]
fn ignore_eos_skips_the_stop() {
    let mut state = GenerationState::new(3, 1024, 455);
    state.append(&[1024, 1024, 1024, 455], true);
    assert!(state.eos_frame.is_none());
    assert_eq!(state.generated, vec![vec![1024, 1024, 1024]]);
}

#[test]
fn config_defaults_and_moe_layout() {
    let config = ModelConfig::from_json(&read_json("generate/config.json")).unwrap();
    assert!(!config.is_moe_layer(0));
    assert!(config.is_moe_layer(1));
    assert!(config.is_moe_layer(2));
    assert!(!config.is_moe_layer(3));
    assert_eq!(config.num_experts_per_tok(1), 1);
    assert_eq!(config.num_experts_per_tok(2), 2);
    assert_eq!(config.frame_width(), 4);
}

/// The `(field, why)` of a `BadConfig` load failure; any other outcome
/// fails the test.
fn config_error(value: serde_json::Value) -> (String, String) {
    match ModelConfig::from_json(&value) {
        Err(SpeechError::BadConfig { field, why }) => (field, why),
        other => panic!("expected BadConfig, got {other:?}"),
    }
}

#[test]
fn zero_head_dim_and_multiple_of_are_bad_config_not_panics() {
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "head_dim": 0})).0,
        "head_dim"
    );
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "multiple_of": 0})).0,
        "multiple_of"
    );
}

#[test]
fn gqa_ratio_must_be_an_exact_positive_divisor() {
    // The default n_heads is dim / head_dim = 16.
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "n_kv_heads": 0})).0,
        "n_kv_heads"
    );
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "n_kv_heads": 3})).0,
        "n_kv_heads"
    );
    assert!(
        ModelConfig::from_json(&serde_json::json!({"text_vocab": 512, "n_kv_heads": 8})).is_ok()
    );
}

#[test]
fn moe_topk_must_be_between_one_and_the_expert_count() {
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "moe_router_topk": 0})).0,
        "moe_router_topk"
    );
    assert_eq!(
        config_error(serde_json::json!({
            "text_vocab": 512, "moe_n_experts": 4, "moe_router_topk": 5
        }))
        .0,
        "moe_router_topk"
    );
    // A per-layer override is checked the same way.
    assert_eq!(
        config_error(serde_json::json!({
            "text_vocab": 512, "moe_n_experts": 4, "special_topk_layers": {"3": 0}
        }))
        .0,
        "moe_router_topk"
    );
}

#[test]
fn codebook_layout_is_bounded_by_the_silence_table() {
    // The silence prompt table is 9 columns wide.
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "n_codebooks": 10})).0,
        "n_codebooks"
    );
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "n_codebooks": 0})).0,
        "n_codebooks"
    );
    assert_eq!(
        config_error(serde_json::json!({"text_vocab": 512, "codebook_size": 0})).0,
        "codebook_size"
    );
}

#[test]
fn balancing_strategy_accepts_only_the_two_known_names() {
    let (field, _) = config_error(serde_json::json!({
        "text_vocab": 512, "moe_balancing_strategy": "quantil"
    }));
    assert_eq!(field, "moe_balancing_strategy");
    let (field, _) = config_error(serde_json::json!({
        "text_vocab": 512, "moe_balancing_strategy": 1
    }));
    assert_eq!(field, "moe_balancing_strategy");
    let quantile = ModelConfig::from_json(&serde_json::json!({
        "text_vocab": 512, "moe_balancing_strategy": " Quantile "
    }))
    .unwrap();
    assert_eq!(quantile.moe_balancing_strategy, "quantile");
    // An absent field keeps the legacy default.
    let absent = ModelConfig::from_json(&serde_json::json!({"text_vocab": 512})).unwrap();
    assert_eq!(absent.moe_balancing_strategy, "legacy");
}

#[test]
fn quality_features_and_special_topk_fail_loudly() {
    // An unknown feature name used to count as 0 buckets.
    let (field, _) = config_error(serde_json::json!({
        "text_vocab": 512,
        "quality_features": ["clarity"],
        "quality_buckets": {"other": [1, 2]}
    }));
    assert_eq!(field, "quality_features");
    // A non-integer per-layer top-k used to become top-1.
    let (field, _) = config_error(serde_json::json!({
        "text_vocab": 512, "moe_n_experts": 4, "special_topk_layers": {"3": "two"}
    }));
    assert_eq!(field, "special_topk_layers");
}

#[test]
fn neighbouring_seeds_do_not_share_step_streams() {
    // Under the old `seed + step` rule, seed 1000 at step 1 equaled seed
    // 1001 at step 0. The derived per-step seeds must stay disjoint.
    let steps = 8;
    let a: Vec<u64> = (0..steps).map(|k| super::step_seed(1000, k)).collect();
    let b: Vec<u64> = (0..steps).map(|k| super::step_seed(1001, k)).collect();
    for x in &a {
        assert!(!b.contains(x), "seed streams overlap at {x:#x}");
    }
    let mut all = a.clone();
    all.sort_unstable();
    all.dedup();
    assert_eq!(all.len(), steps);
}
